head.b:skin:
:root{

--primary:#2563EB;
--secondary:#0EA5E9;
--background:#F8FAFC;
--card:#FFFFFF;
--text:#111827;

}

*{
margin:0;
padding:0;
box-sizing:border-box;
}

body{

font-family:Arial,sans-serif;

background:var(--background);

color:var(--text);

line-height:1.6;

}

a{

text-decoration:none;

color:inherit;

}

.container{

width:92%;

max-width:1200px;

margin:auto;

}
